`timescale 1ps/1ps

`ifndef PH1P_DDRPHY_SIM
`include "../include/ph1p_mis_define.vh"
`endif

module alc_mc_top #(
    parameter tCK                  = 1876    ,
    parameter DRAM_TYPE            = "DDR3"  ,
    parameter ECC                  = "ON"   ,
    parameter ADDR_ORDER           = "ROW_COL_BANK",
    parameter REORDER              = "STRICT",
    parameter DX_NUM               = 2       ,
    parameter CWL                  = 8       ,
    parameter BG_WIDTH             = 0       ,
    parameter BA_WIDTH             = 3       ,
    parameter ROW_WIDTH            = 13      ,
    parameter COL_WIDTH            = 10      ,

    parameter MC_ADDR_WIDTH        = BG_WIDTH + BA_WIDTH + ROW_WIDTH + COL_WIDTH,
    parameter MC_DATA_WIDTH        = (ECC == "ON") ? (DX_NUM-1)*8*8 : DX_NUM*8*8,
    parameter MC_MASK_WIDTH        = (ECC == "ON") ? (DX_NUM-1)*8   : DX_NUM*8  
) (
    //System input
    input                                   clk                ,
    input                                   rst                ,
    input                                   ddrphy_rdy         ,

    //User Interface
    input         [MC_ADDR_WIDTH-1 : 0]     paxi_awaddr        ,
    input                                   paxi_awvalid       ,
    output                                  paxi_awready       ,

    input        [ MC_DATA_WIDTH-1 : 0]     paxi_wdata         ,
    input        [ MC_MASK_WIDTH-1 : 0]     paxi_wstrb         ,
    input                                   paxi_wvalid        ,
    input                                   paxi_wlast         ,
    output                                  paxi_wready        ,

    // Write Response Port
    output       [               1 : 0]     paxi_bresp         ,
    output                                  paxi_bvalid        ,
    input                                   paxi_bready        ,
    // Read Address Ports
    input        [ MC_ADDR_WIDTH-1 : 0]     paxi_araddr        ,
    input                                   paxi_arvalid       ,
    output                                  paxi_arready       ,

    // Read Data Ports
    output       [ MC_DATA_WIDTH-1 : 0]     paxi_rdata         ,
    output                                  paxi_rlast         ,
    output                                  paxi_rvalid        ,
    input                                   paxi_rready        ,

    // ddrphy host interface
    output                                  dhi_cmd_vld_p0     ,
    output                                  dhi_cmd_vld_p1     ,
    output                                  dhi_cmd_vld_p2     ,
    output                                  dhi_cmd_vld_p3     ,
    output       [            32-1 : 0]     dhi_cmd_code_p0    ,
    output       [            32-1 : 0]     dhi_cmd_code_p1    ,
    output       [            32-1 : 0]     dhi_cmd_code_p2    ,
    output       [            32-1 : 0]     dhi_cmd_code_p3    ,

    input                                   dhi_rdata_vld      ,
    input        [    DX_NUM*8*8-1 : 0]     dhi_rdata          ,

    input                                   dhi_wdata_en       ,
    output       [    DX_NUM*8*8-1 : 0]     dhi_wdata          ,
    output       [    DX_NUM*8  -1 : 0]     dhi_wmask          
);

///////////////////////////////////////////////////////////////////////////////////////////////////
//  Local Parameter Definition
///////////////////////////////////////////////////////////////////////////////////////////////////
localparam  ECC_OREG          = 0;

localparam  PHY_DX_NUM        = DX_NUM;
localparam  USR_DX_NUM        = (ECC == "ON") ? (DX_NUM-1) : DX_NUM;

localparam  CS_WIDTH          = 1;
localparam  CKE_WIDTH         = 1;
localparam  ODT_WIDTH         = 1;
localparam  ADDR_WIDTH        = (DRAM_TYPE == "DDR4") ? 17 : ROW_WIDTH;

localparam  DBAW_R            = 5;
localparam  DBAW_W            = 4;


`ifdef PH1P_DDRPHY_SIM
    `ifdef DRAM_DDR4 // L2
        `include "ddr4_parameter.vh"
    `elsif DRAM_DDR3  // L2
        `include "ddr3_parameter.vh"
    `elsif DRAM_DDR2  // L2
        `include "ddr2_parameter.vh"
    `else // L2
        `include "ddr3_parameter.vh"
    `endif // L2
`else // L1
    `ifdef DRAM_DDR4 // L2
        `include "../timing/ddr4/ddr4_parameter.vh"
    `elsif DRAM_DDR3  // L2
        `include "../timing/ddr3/ddr3_parameter.vh"
    `else  // L2
        `include "../timing/ddr2/ddr2_parameter.vh"
    `endif // L2
`endif // L1

`ifdef DRAM_DDR4
localparam nRTW = CL + 4 - CWL + 2; // RL + BL/2 - WL + 2tCK + X
`elsif DRAM_DDR3
localparam nRTW = CL + nCCD + 2 - CWL; // RL + tCCD + 2tCK - WL + X
`elsif DRAM_DDR2
localparam nRTW = 6; // BL=4 : 4tCK; BL=8 : 6tCK
`endif


